  // message request. One code for every untrusted state, so it reveals nothing
  // the caller's own request does not; the ring is never delivered (DM call
  // review D-03).
  CALL_REQUIRES_ACCEPTANCE: "CALL_REQUIRES_ACCEPTANCE",
